try{if($nama===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Nama atau email tidak valid.');$s=$pdo->prepare('SELECT password FROM users WHERE id=?');$s->execute([$_SESSION['user_id']]);$hash=$s->fetchColumn();if($new!==''){if(!password_verify($current,$hash))throw new RuntimeException('Password saat ini tidak sesuai.');if(strlen($new)<10)throw new RuntimeException('Password baru minimal 10 karakter.');$s=$pdo->prepare('UPDATE users SET nama=?,email=?,password=?,updated_at=NOW() WHERE id=?');$s->execute([$nama,$email,password_hash($new,PASSWORD_DEFAULT),$_SESSION['user_id']]);}else{$s=$pdo->prepare('UPDATE users SET nama=?,email=?,updated_at=NOW() WHERE id=?');$s->execute([$nama,$email,$_SESSION['user_id']]);}$_SESSION['nama']=$nama;flash('success','Profil berhasil diperbarui.');}catch(Throwable $e){flash('danger',$e instanceof PDOException?'Email mungkin sudah digunakan.':$e->getMessage());}redirect('profil');
